function renderMenus(lang){
  const zh = lang === 'zh';
  document.getElementById('sidebarMenuList').innerHTML = MENU.map((m, i) =>
    '<button type="button" class="sidebar-nav-item' + (i === activeMenuIdx ? ' active' : '') + '" data-menu-idx="' + i + '">' +
      '<span class="nav-item-index">' + ICONS[m.icon] + '</span>' +
      '<span class="nav-item-label">' + (zh ? m.zh : m.en) + '</span>' +
      '<span class="nav-item-tag">' + (zh ? MENU_BADGES[i].zh : MENU_BADGES[i].en) + '</span>' +
    '</button>').join('');
  document.getElementById('quickToolBar').innerHTML = MENU.map((m, i) =>
    '<button type="button" class="tool-chip' + (i === activeMenuIdx ? ' active' : '') + '" data-menu-idx="' + i + '">' +
      '<span class="tool-chip-inner">' + ICONS[m.icon] + '<span>' + (zh ? m.mZh : m.mEn) + '</span></span>' +
    '</button>').join('');
}
document.addEventListener('click', e => {
  const item = e.target.closest('[data-menu-idx]');
  if (item){ activeMenuIdx = Number(item.getAttribute('data-menu-idx')); renderMenus(currentLang); toggleMobileSidebar(false); return; }
  if (e.target.closest('[data-menu-home]')){ e.preventDefault(); activeMenuIdx = 0; renderMenus(currentLang); toggleMobileSidebar(false); }
});

