let isDarkMode = document.documentElement.getAttribute('data-dark') === 'true';

function applyTheme(idx){
  currentThemeIdx = idx;
  const th = allThemes[idx]; if (!th) return;
  const root = document.documentElement;
  root.style.setProperty('--orb-color-1', th.orb1);
  root.style.setProperty('--orb-color-2', th.orb2);
  root.style.setProperty('--refresh-btn-bg', th.refreshBg);
  root.style.setProperty('--send-circle-bg', th.sendCircleBg);
  root.style.setProperty('--theme-accent', th.accent);
  root.style.setProperty('--theme-tag-bg', th.tagBg);
  root.style.setProperty('--theme-tag-text', th.tagText);
  root.style.setProperty('--search-glow', th.glow);
  if (th.isHolo) root.setAttribute('data-holo', 'true'); else root.removeAttribute('data-holo');
  if (!isDarkMode){
    root.style.setProperty('--page-bg', th.pageBg);
    const mt = document.querySelector('meta[name="theme-color"]'); if (mt) mt.setAttribute('content', th.pageBg);
  }
  const ol = document.getElementById('orbLeft'), or2 = document.getElementById('orbRight');
  if (ol && or2){
    if (!th.isHolo){ const sh = idx % 2 === 0 ? 1 : -1;
      ol.style.transform = 'translate(' + (sh*14) + 'px,' + (-sh*8) + 'px) scale(' + (1+sh*0.05) + ')';
      or2.style.transform = 'translate(' + (-sh*14) + 'px,' + (sh*8) + 'px) scale(' + (1-sh*0.05) + ')';
    } else { ol.style.transform = ''; or2.style.transform = ''; }
  }
  updateSwatchActiveState();
}
