function toggleDarkMode(){
  isDarkMode = !isDarkMode;
  const root = document.documentElement;
  themeBtn.classList.add('rotating'); setTimeout(() => themeBtn.classList.remove('rotating'), 450);
  const mt = document.querySelector('meta[name="theme-color"]');
  if (isDarkMode){ root.setAttribute('data-dark', 'true'); root.style.setProperty('--page-bg', '#090D16'); if (mt) mt.setAttribute('content', '#0B1120'); }
  else { root.removeAttribute('data-dark'); const th = allThemes[currentThemeIdx]; root.style.setProperty('--page-bg', th.pageBg); if (mt) mt.setAttribute('content', th.pageBg); }
  writeSharedA();
}
(function initThemeButtonGestures(){
  let pressTimer = null, isLong = false, isDown = false, lastHover = null;
  themeBtn.addEventListener('pointerdown', e => {
    if (e.button && e.button !== 0) return;
    isDown = true; isLong = false; lastHover = null;
    themeBtn.classList.add('pressing');
    try { themeBtn.setPointerCapture(e.pointerId); } catch(_){}
    pressTimer = setTimeout(() => { if (!isDown) return; isLong = true; openThemePanel(); }, 340);
  });
  themeBtn.addEventListener('pointermove', e => {
    if (!isDown || !isLong) return;
    const target = document.elementFromPoint(e.clientX, e.clientY);
    const item = target ? target.closest('.theme-swatch-item') : null;
    document.querySelectorAll('.theme-swatch-item').forEach(el => el.classList.toggle('sliding-hover', el === item));
    if (item){ const idx = Number(item.getAttribute('data-theme-idx'));
      if (idx !== lastHover){ lastHover = idx; applyTheme(idx); if (navigator.vibrate) navigator.vibrate(8); } }
  });
  const finish = () => {
    if (!isDown) return;
    isDown = false; clearTimeout(pressTimer); themeBtn.classList.remove('pressing');
    if (!isLong){
      if (document.getElementById('themePopover').classList.contains('open')) closeThemePanel();
      else toggleDarkMode();
    } else if (lastHover !== null){ persistTheme(); closeThemePanel(); }
  };
  themeBtn.addEventListener('pointerup', finish);
  themeBtn.addEventListener('pointercancel', finish);
  themeBtn.addEventListener('contextmenu', e => e.preventDefault());
})();

