let sidebarLockedScrollY = null;
function toggleMobileSidebar(open){
  const mobileOpen = !!open && window.innerWidth <= 1120;
  const wasOpen = sidebarLockedScrollY !== null;
  if(mobileOpen && !wasOpen){
    sidebarLockedScrollY = window.scrollY;
    document.body.style.top = -sidebarLockedScrollY + 'px';
  }
  document.getElementById('appSidebar').classList.toggle('open', mobileOpen);
  document.getElementById('sidebarBackdrop').classList.toggle('open', mobileOpen);
  document.documentElement.classList.toggle('sidebar-drawer-open', mobileOpen);
  if(!mobileOpen && wasOpen){
    const y = sidebarLockedScrollY;
    sidebarLockedScrollY = null;
    document.body.style.top = '';
    window.scrollTo({top:y,behavior:'instant'});
  }
}
document.getElementById('sidebarBackdrop').addEventListener('click', () => toggleMobileSidebar(false));
document.getElementById('drawerCloseBtn').addEventListener('click', () => toggleMobileSidebar(false));
