let toastTimer = null;
function toast(msg, isError){
  const el = document.getElementById('auraToast');
  el.textContent = msg;
  el.classList.toggle('error', !!isError);
  el.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => el.classList.remove('show'), 2200);
}

/* ================= TOTP core (RFC 4226 / 6238, HMAC-SHA1) ================= */
const B32 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
function base32Decode(str){
  const clean = String(str).toUpperCase().replace(/=+$/,'').replace(/[^A-Z2-7]/g,'');
  if (!clean) return null;
  let bits = 0, value = 0; const out = [];
  for (const ch of clean){
    value = (value << 5) | B32.indexOf(ch); bits += 5;
    if (bits >= 8){ out.push((value >>> (bits - 8)) & 0xff); bits -= 8; }
  }
  return new Uint8Array(out);
}
function isValidSecret(s){
  if (!s || !/^[0-9a-zA-Z]+$/.test(s)) return false;
  try { const d = base32Decode(s); return !!d && d.length >= 6; } catch(e){ return false; }
}
async function totp(secret, epochSec){
  const keyBytes = base32Decode(secret);
  const counter = Math.floor(epochSec / 30);
  const msg = new ArrayBuffer(8); const view = new DataView(msg);
  view.setUint32(4, counter >>> 0); view.setUint32(0, Math.floor(counter / 4294967296));
  const key = await crypto.subtle.importKey('raw', keyBytes, {name:'HMAC', hash:'SHA-1'}, false, ['sign']);
  const sig = new Uint8Array(await crypto.subtle.sign('HMAC', key, msg));
  const offset = sig[sig.length - 1] & 0xf;
  const binary = ((sig[offset] & 0x7f) << 24) | ((sig[offset+1] & 0xff) << 16) | ((sig[offset+2] & 0xff) << 8) | (sig[offset+3] & 0xff);
  return String(binary % 1000000).padStart(6,'0');
}
/* Same parsing rule as original get-2fa-otp.js:
   per line split by | , title = first email-like field or first field,
   secret = field[2] or field[0] that decodes as base32. */
function parseSecrets(text){
  const emailRe = /\S+@\S+\.\S+/;
  const seen = new Set(); const out = [];
  for (const rawLine of String(text).split('\n')){
    const parts = rawLine.replace(/ /g,'').split('|');
    if (!parts.length || !parts[0]) continue;
    const title = parts.find(p => emailRe.test(p)) || parts[0];
    const secret = [parts[2], parts[0]].find(isValidSecret);
    if (secret && !seen.has(secret.toUpperCase())){ seen.add(secret.toUpperCase()); out.push({title, secret:secret.toUpperCase()}); }
  }
  return out;
}

/* ================= Form + result rendering ================= */
const textarea  = document.getElementById('SECRET2FA');
const btnGet    = document.getElementById('btnGet');
const btnGetLabel = document.getElementById('btnGetLabel');
const inlineClearX = document.getElementById('inlineClearX');
const btnMask   = document.getElementById('btnMask');
const lineCount = document.getElementById('lineCount');
const otpList   = document.getElementById('otpList');
const otpEmpty  = document.getElementById('otpEmpty');
const wrapEl    = document.getElementById('textareaWrap');
let activated = false;
let codesGenerated = false;
let lastSignature = '';

function emptyNoteHtml(){ return '<div class="results-empty-note">' + i18n[currentLang].emptyState + '</div>'; }
function refreshGetBtn(){
  btnGet.disabled = codesGenerated || !textarea.value.trim();
  btnGetLabel.textContent = i18n[currentLang][codesGenerated ? 'generatedBtn' : 'getCodeBtn'];
}
function updateMeta(){
  const n = textarea.value ? textarea.value.split('\n').filter(l => l.trim()).length : 0;
  lineCount.textContent = n + ' ' + i18n[currentLang].lines;
  refreshGetBtn();
  inlineClearX.classList.toggle('visible', !!textarea.value);
}
textarea.addEventListener('input', () => { codesGenerated = false; wrapEl.classList.remove('error'); otpEmpty.classList.remove('show'); updateMeta(); if (activated) renderOtpCodes(true); });
textarea.addEventListener('keydown', e => { if ((e.ctrlKey || e.metaKey) && e.key === 'Enter'){ e.preventDefault(); document.getElementById('formSecret').requestSubmit(); } });
function clearInput(){
  textarea.value = ''; activated = false; codesGenerated = false; lastSignature = '';
  otpList.innerHTML = emptyNoteHtml(); updateMeta(); textarea.focus();
}
inlineClearX.addEventListener('click', clearInput);
btnMask.addEventListener('click', () => textarea.classList.toggle('masked-mode'));

document.getElementById('formSecret').addEventListener('submit', e => {
  e.preventDefault();
  const secrets = parseSecrets(textarea.value);
  if (!secrets.length){
    wrapEl.classList.remove('error'); void wrapEl.offsetWidth; wrapEl.classList.add('error');
    otpEmpty.classList.add('show'); toast(i18n[currentLang].toastInvalid, true); return;
  }
  activated = true; codesGenerated = true; refreshGetBtn(); renderOtpCodes(true);
});

/* button ripple */
btnGet.addEventListener('click', e => {
  const r = document.createElement('span'); r.className = 'ripple';
  const rect = btnGet.getBoundingClientRect(); const size = Math.max(rect.width, rect.height);
  r.style.width = r.style.height = size + 'px';
  r.style.left = (e.clientX - rect.left - size/2) + 'px'; r.style.top = (e.clientY - rect.top - size/2) + 'px';
  btnGet.appendChild(r); setTimeout(() => r.remove(), 600);
});

function secretPreview(secret){ return '\u2022\u2022\u2022\u2022 ' + secret.slice(-4); }
function updateRings(remain){
  const off = (81.68 * (1 - remain/30)).toFixed(2);
  document.querySelectorAll('.totp-ring-wrap').forEach(w => {
    w.classList.toggle('urgent', remain <= 5);
    const fg = w.querySelector('.ring-fg'); if (fg) fg.style.strokeDashoffset = off;
    const sec = w.querySelector('.ring-sec'); if (sec) sec.textContent = remain;
  });
}
async function renderOtpCodes(force){
  const remain = 30 - (Math.floor(Date.now()/1000) % 30);
  updateRings(remain);
  if (!activated) return;
  const secrets = parseSecrets(textarea.value);
  if (!secrets.length){ otpList.innerHTML = emptyNoteHtml(); return; }
  const now = Math.floor(Date.now()/1000);
  const codes = await Promise.all(secrets.map(s => totp(s.secret, now)));
  const signature = secrets.map(s => s.secret).join(',') + '|' + Math.floor(now/30) + '|' + currentLang;
  if (!force && signature === lastSignature) return;
  lastSignature = signature;
  const t = i18n[currentLang];
  otpList.innerHTML = secrets.map((s, i) =>
    '<div class="totp-code-item">' +
      '<div class="totp-label-line">' +
        '<span class="totp-account-tag">' + escapeHtml(s.title && s.title.toUpperCase() !== s.secret ? shortTitle(s.title) : t.codeLabel) + '</span>' +
        '<span class="totp-secret-preview">' + secretPreview(s.secret) + '</span>' +
      '</div>' +
      '<div class="totp-digits-row">' +
        '<div class="totp-big-code">' + codes[i] + '</div>' +
        '<div class="totp-ring-wrap"><svg class="totp-ring" viewBox="0 0 30 30"><circle class="ring-bg" cx="15" cy="15" r="13"></circle><circle class="ring-fg" cx="15" cy="15" r="13"></circle></svg><span class="ring-sec">' + remain + '</span></div>' +
        '<button type="button" class="copy-code-btn" data-code="' + codes[i] + '">' + ICONS.copy + '<span>' + t.copyBtn + '</span></button>' +
      '</div>' +
    '</div>'
  ).join('');
  updateRings(remain);
}
function escapeHtml(s){ return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function shortTitle(s){ return s.length > 26 ? s.slice(0,26) + '…' : s; }


otpList.addEventListener('click', async e => {
  const btn = e.target.closest('.copy-code-btn'); if (!btn) return;
  const code = btn.getAttribute('data-code');
  try { await navigator.clipboard.writeText(code); }
  catch(err){
    const ta = document.createElement('textarea'); ta.value = code; document.body.appendChild(ta); ta.select();
    try { document.execCommand('copy'); } catch(e2){ toast(i18n[currentLang].toastCopyFail, true); ta.remove(); return; }
    ta.remove();
  }
  const span = btn.querySelector('span'); const old = span.textContent;
  btn.classList.add('copied'); span.textContent = i18n[currentLang].copiedBtn;
  toast(i18n[currentLang].toastCopied + ': ' + code);
  setTimeout(() => { btn.classList.remove('copied'); span.textContent = old; }, 1600);
});

/* per-second tick: countdown + auto refresh at window rollover (same as original) */
setInterval(() => { renderOtpCodes(false); }, 1000);

